referenceSolutions.javascript:
export function solve(query) {
  const text = query.startsWith("?") ? query.slice(1) : query;
  const decode = (s) => decodeURIComponent(s.replace(/\+/g, " "));
  return text
    .split("&")
    .filter(Boolean)
    .map((part) => {
      const i = part.indexOf("=");
      return i < 0 ? [decode(part), ""] : [decode(part.slice(0, i)), decode(part.slice(i + 1))];
    });
}

